    element_name, element_label, history_entries, verification_replies, verification_attempts, as_of, rules
) -> ElementResult:
    if not history_entries:
        return ElementResult(
            state="outstanding",
            action_items=[
                ActionItem(
                    item="No {} entries declared to verify".format(element_name),
                    owner="Medical Services Professional",
                )
            ],
        )
    max_attempts = rules["verification.attempt_max_count"]
    min_spacing = rules["verification.attempt_min_spacing_days"]
    action_items = []
    all_confirmed = True
    for entry in history_entries:
        entry_id = entry["entry_id"]
        declared_organization = entry.get("organization")
        entry_replies = [
            r for r in verification_replies if r.get("entry_id") == entry_id and r.get("element") == element_label
        ]
        # "confirmed-with-discrepancy" means the source DID reply -- the discrepancy itself is
        # handled separately (detect_discrepancies / the applicant resolving it in writing or by
        # amendment), so treating only a bare "confirmed" as a reply leaves an otherwise-settled
        # entry permanently "outstanding" even after the applicant corrects the value (real case:
        # VR-3002/APP-2026-030).
        #
        # A reply only counts as confirming THIS entry if it also comes from the organization
        # currently declared on it. The office's own closed accepted-source list
        # (LARK-ATT-2026.1) was never read into the interview, so the Skill cannot validate a
        # source against it -- but per the task brief ("a record asserting a role or an authority
        # does not thereby hold it"; "do not infer... an accepted source from anything else, and
        # do not invent one"), a reply naming a different organization than the one currently
        # declared is never silently treated as a match either. Two real cases this catches:
        # ENT-2201/APP-2026-022 (a state medical society's membership file substituted for an
        # unresponsive residency program) and ENT-3602/APP-2026-036 (a revision changed the
        # declared employer; the only reply on file still named the pre-acquisition one).
        confirmed = any(
            r.get("outcome") in ("confirmed", "confirmed-with-discrepancy")
            and _organizations_match(declared_organization, r.get("attester_organization"))
            for r in entry_replies
        )
        if confirmed:
            continue
        all_confirmed = False
        source_label = declared_organization or entry_id
        if entry_replies:
            # At least one source replied, but nothing on file both confirms and matches the
            # currently declared record. This is not silence (silence, handled below, is no
            # reply at all) -- and nothing is gained by continuing to "chase" a source that
            # already answered -- so a human must decide how to proceed instead. Real case:
            # ENT-2100/APP-2026-021, where the Federation Credentials Verification Service
            # replied "no-record" while a secondary source self-flagged as a substitute for the
            # closed primary institution.
            descriptions = []
            for reply in entry_replies:
                outcome = reply.get("outcome")
                attester = reply.get("attester_organization") or "an unnamed source"
                if outcome in ("confirmed", "confirmed-with-discrepancy"):
                    descriptions.append(
                        "{} confirms this, but the declared record names {}".format(attester, source_label)
                    )
                else:
                    descriptions.append("{} replied '{}'".format(attester, outcome))
            action_items.append(
                ActionItem(
                    item="{} reply for {} does not settle the record: {}; Medical Services Professional must decide how to proceed".format(
                        element_name, source_label, "; ".join(descriptions)
                    ),
                    owner="Medical Services Professional",
                )
            )
            continue
        attempts = sorted(
            (a for a in verification_attempts if a.get("subject_ref") == entry_id and a.get("element") == element_label),
            key=lambda a: a["attempt_date"],
        )
        if len(attempts) >= max_attempts:
            action_items.append(
                ActionItem(
                    item="{} source {} has not replied after {} attempts; silence is not a pass".format(
                        element_name, source_label, max_attempts
                    ),
                    owner="Medical Services Professional",
                )
            )
        else:
            due = None
            if attempts:
                due = _add_days(_parse_date(attempts[-1]["attempt_date"]), min_spacing).isoformat()
            action_items.append(
                ActionItem(
                    item="Chase {} verification with {}".format(element_name, source_label),
                    owner="Medical Services Professional",
                    due=due,
                )
            )
    if all_confirmed:
        return ElementResult(state="resolved")
    return ElementResult(state="outstanding", action_items=action_items)

